DO $$ DECLARE d text; old_anchor text := 'd.is_archived=false AND d.trade=''daily_site_report'' AND d.id IS DISTINCT FROM r.id'; BEGIN d := pg_get_functiondef('public.get_site_report(uuid,date)'::regprocedure); IF position(old_anchor IN d)=0 THEN RAISE EXCEPTION 'Report cumulative anchor missing'; END IF; d := replace(d,old_anchor,'d.is_archived=false AND d.trade=''daily_site_report'' AND d.report_status=''submitted'' AND d.measurement_date<=p_date'); EXECUTE d; END $$;
ALTER TABLE public.export_tokens ADD COLUMN expires_at timestamptz;
UPDATE public.export_tokens SET expires_at=created_at+interval '180 days' WHERE expires_at IS NULL;
ALTER TABLE public.export_tokens ALTER COLUMN expires_at SET NOT NULL;
CREATE FUNCTION public.export_token_expiry_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.expires_at IS NULL THEN NEW.expires_at:=NEW.created_at+interval '180 days'; END IF; IF NEW.expires_at IS NULL THEN RAISE EXCEPTION 'Token expiry is required'; END IF; IF NEW.expires_at>NEW.created_at+interval '365 days' THEN RAISE EXCEPTION 'Token expiry cannot exceed 365 days from creation'; END IF; IF TG_OP='INSERT' AND NEW.expires_at<=NEW.created_at THEN RAISE EXCEPTION 'Token expiry must be after creation'; END IF; RETURN NEW; END $$;
CREATE TRIGGER export_token_expiry_guard BEFORE INSERT OR UPDATE ON public.export_tokens FOR EACH ROW EXECUTE FUNCTION public.export_token_expiry_guard();